import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  hoverCardBackdropClasses,
  hoverCardPopupClasses,
  hoverCardPortalClasses,
  hoverCardPositionerClasses,
  hoverCardRootClasses,
  hoverCardTriggerClasses,
} from "./view";

export {
  hoverCardAvatarClasses,
  hoverCardBackdropClasses,
  hoverCardDescriptionClasses,
  hoverCardMetaClasses,
  hoverCardPopupClasses,
  hoverCardPortalClasses,
  hoverCardPositionerClasses,
  hoverCardRootClasses,
  hoverCardTitleClasses,
  hoverCardTriggerClasses,
} from "./view";

export type HoverCardStyle = Readonly<Record<string, string>>;

export type PartViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: HoverCardStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  onOpen: ParentMessage;
  open?: boolean | undefined;
  classes?: string | undefined;
  style?: HoverCardStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  classes?: string | undefined;
  style?: HoverCardStyle | undefined;
}>;

export type BackdropViewConfig<ParentMessage> = Readonly<{
  onClose: ParentMessage;
  classes?: string | undefined;
  style?: HoverCardStyle | undefined;
}>;

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "hover-card"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(hoverCardRootClasses, classes)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  children,
  onOpen,
  open = false,
  classes,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("aria-haspopup", "dialog"),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      h.DataAttribute("slot", "hover-card-trigger"),
      ...(open ? [h.DataAttribute("open", "true")] : []),
      h.OnClick(onOpen),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(hoverCardTriggerClasses, classes)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  classes,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.empty;
  }

  return h.div(
    [
      h.DataAttribute("slot", "hover-card-portal"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(hoverCardPortalClasses, classes)),
    ],
    children
  );
};

export const backdropView = <ParentMessage>({
  onClose,
  classes,
  style,
}: BackdropViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel("Close hover card"),
      h.DataAttribute("slot", "hover-card-backdrop"),
      h.OnClick(onClose),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(hoverCardBackdropClasses, classes)),
    ],
    []
  );
};

export const positionerView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "hover-card-positioner"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(hoverCardPositionerClasses, classes)),
    ],
    children
  );
};

export const popupView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "dialog"),
      h.DataAttribute("slot", "hover-card-popup"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(hoverCardPopupClasses, classes)),
    ],
    children
  );
};

export const hoverCardRootClasses = "relative inline-block";
export const hoverCardTriggerClasses =
  "rounded-md text-sm font-medium text-accent-700 underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";
export const hoverCardPortalClasses = "contents";
export const hoverCardBackdropClasses = "fixed inset-0 z-20";
export const hoverCardPositionerClasses =
  "absolute left-0 top-full z-30 mt-2 w-80";
export const hoverCardPopupClasses =
  "rounded-lg border border-gray-200 bg-white p-4 text-left shadow-lg";
export const hoverCardAvatarClasses =
  "flex h-12 w-12 items-center justify-center rounded-full bg-gray-950 text-sm font-semibold text-white";
export const hoverCardTitleClasses = "text-sm font-semibold text-gray-950";
export const hoverCardDescriptionClasses =
  "mt-1 text-sm leading-6 text-gray-600";
export const hoverCardMetaClasses =
  "mt-3 flex items-center gap-2 text-xs text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as HoverCard from "./index";

const view = (open: boolean): Html => {
  const h = html<string>();

  return HoverCard.rootView<string>({
    children: [
      HoverCard.triggerView<string>({
        open,
        onOpen: "open",
        children: [h.span([], ["@foldkit"])],
      }),
      HoverCard.portalView<string>({
        open,
        children: [
          HoverCard.backdropView<string>({ onClose: "close" }),
          HoverCard.positionerView<string>({
            children: [
              HoverCard.popupView<string>({
                children: [
                  h.div([h.Class(HoverCard.hoverCardAvatarClasses)], ["FK"]),
                  h.h3(
                    [h.Class(HoverCard.hoverCardTitleClasses)],
                    ["@foldkit"]
                  ),
                  h.p(
                    [h.Class(HoverCard.hoverCardDescriptionClasses)],
                    ["A toolkit for Elm-style Effect applications."]
                  ),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Hover Card registry view", () => {
  test("renders trigger and closed state", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view,
      },
      Scene.with(false),
      Scene.expect(Scene.role("button", { name: "@foldkit" })).toHaveAttr(
        "aria-expanded",
        "false"
      ),
      Scene.expect(Scene.role("dialog")).toBeAbsent()
    );
  });

  test("renders controlled popup content", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view,
      },
      Scene.with(true),
      Scene.expect(Scene.role("button", { name: "@foldkit" })).toHaveAttr(
        "aria-expanded",
        "true"
      ),
      Scene.expect(Scene.role("dialog")).toExist(),
      Scene.expect(
        Scene.text("A toolkit for Elm-style Effect applications.")
      ).toExist()
    );
  });
});
